        break

# Inspect writes
write_summaries = []
for w in writes:
    write_summaries.append({
        'api': w.get('api'),
        'name': w.get('name'),
        'args': w.get('args'),
        'result_preview': str(w.get('result'))[:200]
    })

print_json({
    'queries': [],
    'facts': {
        'pristine_song_keys': list(pristine.keys()) if isinstance(pristine, dict) else str(type(pristine)),
        'pristine_song': pristine,
        'write_count': len(writes),
        'writes': write_summaries
    }
})
